# install.ps1 - registers the `ch` command in the PowerShell profile.
#
# Idempotent: it writes between markers and replaces the previous block if one
# already exists. Running it twice duplicates nothing.

$ErrorActionPreference = 'Stop'

$hubRoot = $PSScriptRoot
$begin = '# >>> claude-hub >>>'
$end = '# <<< claude-hub <<<'

$block = @"
$begin
# Claude Code repositories, sessions and memory in one panel.
# Generated by $hubRoot\install.ps1 - edit the whole block or run install again.
function ch { & "$hubRoot\ch.ps1" @args }
$end
"@

$profilePath = $PROFILE
$profileDir = Split-Path -Parent $profilePath

if (-not (Test-Path -LiteralPath $profileDir)) {
    New-Item -ItemType Directory -Path $profileDir -Force | Out-Null
    Write-Host "  created the profile folder: $profileDir" -ForegroundColor DarkGray
}

$existing = ''
if (Test-Path -LiteralPath $profilePath) {
    $existing = Get-Content -LiteralPath $profilePath -Raw -Encoding UTF8
    if ($null -eq $existing) { $existing = '' }
}

$pattern = '(?s)' + [regex]::Escape($begin) + '.*?' + [regex]::Escape($end)
if ([regex]::IsMatch($existing, $pattern)) {
    $updated = [regex]::Replace($existing, $pattern, [System.Text.RegularExpressions.MatchEvaluator] { param($m) $block })
    $action = 'updated'
} else {
    $sep = ''
    if ($existing.Length -gt 0 -and -not $existing.EndsWith("`n")) { $sep = "`r`n" }
    if ($existing.Length -gt 0) { $sep += "`r`n" }
    $updated = $existing + $sep + $block + "`r`n"
    $action = 'added'
}

Set-Content -LiteralPath $profilePath -Value $updated -Encoding UTF8

Write-Host ''
Write-Host "  $action the claude-hub block in:" -ForegroundColor Green
Write-Host "    $profilePath" -ForegroundColor DarkGray
Write-Host ''

# ExecutionPolicy: the profile only loads if the policy allows local scripts.
#
# `Get-ExecutionPolicy` with no scope returns the EFFECTIVE policy, which
# includes the Process scope. An installer run from inside a `powershell
# -ExecutionPolicy Bypass` sees "Bypass" and concludes all is well - but the
# user's normal window does not inherit that and falls back to Restricted.
# That is why this check only looks at the scopes that persist.
$persistentes = Get-ExecutionPolicy -List |
    Where-Object { $_.Scope -ne 'Process' -and $_.ExecutionPolicy -ne 'Undefined' }

$liberado = $false
foreach ($e in $persistentes) {
    if ($e.ExecutionPolicy -in @('RemoteSigned', 'Unrestricted', 'Bypass')) { $liberado = $true }
}

if (-not $liberado) {
    Write-Host '  WARNING: no persistent execution policy allows scripts.' -ForegroundColor Yellow
    Write-Host '  In a normal window the profile will NOT load and `ch` will not exist.' -ForegroundColor Yellow
    Write-Host '  To allow it for your user only (no administrator needed):' -ForegroundColor Yellow
    Write-Host '    Set-ExecutionPolicy -Scope CurrentUser RemoteSigned' -ForegroundColor Cyan
    Write-Host '  To undo it later:' -ForegroundColor DarkGray
    Write-Host '    Set-ExecutionPolicy -Scope CurrentUser Undefined' -ForegroundColor DarkGray
    Write-Host ''
}

Write-Host '  Open a new PowerShell and run:' -ForegroundColor DarkGray
Write-Host '    ch' -ForegroundColor Cyan
Write-Host ''
